/**
 * Server-side port of the app's pure Kotlin rules engine (domain/engine/LudoEngine.kt + domain/model/*).
 *
 * The server is authoritative: it rolls the dice and applies every move, then broadcasts the resulting state.
 * The JSON shape of `state` deliberately matches the Kotlin `GameState` (kotlinx.serialization field names and enum
 * names), so the Android client decodes it straight into its own model and renders it with the same board code.
 *
 * test/engine.test.js replays game traces generated by the Kotlin engine and checks this port step for step.
 */

export const COLORS = Object.freeze(['RED', 'GREEN', 'YELLOW', 'BLUE']); // clockwise turn order == Kotlin ordinal
export const START_INDEX = Object.freeze({ RED: 0, GREEN: 13, YELLOW: 26, BLUE: 39 });
export const TRACK_LENGTH = 52;
export const LAST_TRACK_STEP = 50;
export const HOME_COLUMN_START = 51;
export const FINISH_STEP = 56;
export const TOKENS_PER_PLAYER = 4;
export const IN_YARD = -1;

const ordinal = (color) => COLORS.indexOf(color);
export const starIndex = (color) => (START_INDEX[color] + 8) % TRACK_LENGTH;
export const SAFE_TRACK_INDICES = new Set(COLORS.flatMap((c) => [START_INDEX[c], starIndex(c)]));
export const tokenId = (color, index) => ordinal(color) * TOKENS_PER_PLAYER + index;

/** Index on the shared 52-square track, or null in the yard / home column / finished. */
export function trackIndex(color, step) {
  return step >= 0 && step <= LAST_TRACK_STEP ? (START_INDEX[color] + step) % TRACK_LENGTH : null;
}

/** Default colours for N players, human/host colour first (mirrors PlayerColor.defaultsFor). */
export function defaultColors(count, hostColor = 'BLUE') {
  const next = (c) => COLORS[(ordinal(c) + 1) % 4];
  const opposite = (c) => COLORS[(ordinal(c) + 2) % 4];
  if (count === 2) return [hostColor, opposite(hostColor)];
  if (count === 3) return [hostColor, next(hostColor), next(next(hostColor))];
  return [...COLORS];
}

/**
 * New game. `players` = [{ color, name, type }] (type 'HUMAN' | 'COMPUTER'); they are seated in clockwise order.
 */
export function newGame(players) {
  if (players.length < 2 || players.length > 4) throw new Error('Ludo needs 2 to 4 players');
  if (new Set(players.map((p) => p.color)).size !== players.length) throw new Error('Colours must be unique');
  const seated = [...players].sort((a, b) => ordinal(a.color) - ordinal(b.color));
  return {
    players: seated.map(({ color, name, type }) => ({ color, name, type: type ?? 'HUMAN' })),
    tokens: seated.flatMap((p) =>
      Array.from({ length: TOKENS_PER_PLAYER }, (_, i) => ({ id: tokenId(p.color, i), color: p.color, index: i, step: IN_YARD })),
    ),
    currentPlayerIndex: 0,
    phase: 'ROLL',
    dice: null,
    consecutiveSixes: 0,
    legalMoves: [],
    finishOrder: [],
    turnNumber: 1,
  };
}

export const currentColor = (state) => state.players[state.currentPlayerIndex].color;
const tokensOf = (state, color) => state.tokens.filter((t) => t.color === color);
const hasFinished = (state, color) => state.finishOrder.includes(color);
const isFinishedToken = (t) => t.step === FINISH_STEP;

export function legalMoves(state, color, dice) {
  const moves = [];
  for (const t of tokensOf(state, color)) {
    if (isFinishedToken(t)) continue;
    if (t.step === IN_YARD) {
      if (dice === 6) moves.push({ tokenId: t.id, fromStep: IN_YARD, toStep: 0, dice });
    } else if (t.step + dice <= FINISH_STEP) {
      moves.push({ tokenId: t.id, fromStep: t.step, toStep: t.step + dice, dice });
    }
  }
  return moves;
}

/** Apply a dice roll for the current player. Returns { state, events }. */
export function roll(state, value) {
  if (!Number.isInteger(value) || value < 1 || value > 6) throw new Error('Dice must be 1..6');
  if (state.phase !== 'ROLL') throw new Error(`Not expecting a roll in phase ${state.phase}`);
  const color = currentColor(state);
  const events = [{ type: 'DiceRolled', color, value }];
  const sixes = value === 6 ? state.consecutiveSixes + 1 : 0;

  if (sixes >= 3) {
    events.push({ type: 'ThreeSixes', color });
    return passTurn({ ...state, dice: value, consecutiveSixes: 0, legalMoves: [] }, events);
  }

  const moves = legalMoves(state, color, value);
  if (moves.length === 0) {
    events.push({ type: 'NoLegalMove', color, dice: value });
    const next = { ...state, dice: value, consecutiveSixes: sixes, legalMoves: [] };
    if (value === 6) {
      events.push({ type: 'ExtraTurn', color, reason: 'ROLLED_SIX' });
      return { state: { ...next, phase: 'ROLL' }, events };
    }
    return passTurn(next, events);
  }
  return { state: { ...state, dice: value, consecutiveSixes: sixes, legalMoves: moves, phase: 'MOVE' }, events };
}

const sameMove = (a, b) => a.tokenId === b.tokenId && a.fromStep === b.fromStep && a.toStep === b.toStep && a.dice === b.dice;

/** Apply one of the legal moves for the current player. Returns { state, events }. */
export function move(state, mv) {
  if (state.phase !== 'MOVE') throw new Error(`Not expecting a move in phase ${state.phase}`);
  const legal = state.legalMoves.find((m) => sameMove(m, mv));
  if (!legal) throw new Error('Illegal move');

  const mover = state.tokens.find((t) => t.id === legal.tokenId);
  const color = mover.color;
  const events = [{ type: 'TokenMoved', move: legal }];
  if (legal.fromStep === IN_YARD) events.push({ type: 'TokenEnteredBoard', tokenId: mover.id });

  const moved = { ...mover, step: legal.toStep };
  let tokens = state.tokens.map((t) => (t.id === moved.id ? moved : t));
  let extraTurn = legal.dice === 6 ? 'ROLLED_SIX' : null;

  const landing = trackIndex(color, moved.step);
  if (landing !== null) {
    if (SAFE_TRACK_INDICES.has(landing)) {
      events.push({ type: 'LandedOnSafeSquare', tokenId: moved.id });
    } else {
      const victims = tokens.filter((t) => t.color !== color && trackIndex(t.color, t.step) === landing);
      if (victims.length > 0) {
        const ids = new Set(victims.map((v) => v.id));
        tokens = tokens.map((t) => (ids.has(t.id) ? { ...t, step: IN_YARD } : t));
        events.push({ type: 'TokensCaptured', byTokenId: moved.id, capturedTokenIds: victims.map((v) => v.id) });
        extraTurn = 'CAPTURED';
      }
    }
  }

  let finishOrder = state.finishOrder;
  if (isFinishedToken(moved)) {
    events.push({ type: 'TokenFinished', tokenId: moved.id });
    extraTurn = 'TOKEN_HOME';
    if (tokens.filter((t) => t.color === color).every(isFinishedToken)) {
      finishOrder = [...finishOrder, color];
      events.push({ type: 'PlayerFinished', color, rank: finishOrder.length });
    }
  }

  const afterMove = { ...state, tokens, finishOrder, legalMoves: [] };
  const stillPlaying = afterMove.players.map((p) => p.color).filter((c) => !finishOrder.includes(c));
  if (stillPlaying.length <= 1) {
    const ranking = [...finishOrder, ...stillPlaying];
    events.push({ type: 'GameOver', ranking });
    return { state: { ...afterMove, finishOrder: ranking, phase: 'GAME_OVER' }, events };
  }

  if (extraTurn !== null && !finishOrder.includes(color)) {
    events.push({ type: 'ExtraTurn', color, reason: extraTurn });
    const sixes = legal.dice === 6 ? afterMove.consecutiveSixes : 0;
    return { state: { ...afterMove, phase: 'ROLL', consecutiveSixes: sixes }, events };
  }
  return passTurn({ ...afterMove, consecutiveSixes: 0 }, events);
}

function passTurn(state, events) {
  let idx = state.currentPlayerIndex;
  for (let i = 0; i < state.players.length; i++) {
    idx = (idx + 1) % state.players.length;
    if (!hasFinished(state, state.players[idx].color)) {
      events.push({ type: 'TurnPassed', toColor: state.players[idx].color });
      return {
        state: { ...state, currentPlayerIndex: idx, phase: 'ROLL', consecutiveSixes: 0, legalMoves: [], turnNumber: state.turnNumber + 1 },
        events,
      };
    }
  }
  return { state: { ...state, phase: 'GAME_OVER' }, events };
}

/**
 * Move choice for an absent player (turn timer expired / disconnected). A compact version of the app's
 * HeuristicBotStrategy: finish > capture > safe square > leave yard > progress, avoiding squares under threat.
 */
export function chooseAutoMove(state) {
  const moves = state.legalMoves;
  if (moves.length <= 1) return moves[0];
  const score = (m) => {
    const token = state.tokens.find((t) => t.id === m.tokenId);
    const color = token.color;
    let s = m.toStep * 1.5;
    if (m.toStep === FINISH_STEP) s += 1000;
    const to = trackIndex(color, m.toStep);
    if (to !== null) {
      const safe = SAFE_TRACK_INDICES.has(to);
      const victims = state.tokens.filter((t) => t.color !== color && trackIndex(t.color, t.step) === to);
      if (!safe && victims.length) s += 800 + 40 * victims.length;
      if (safe) s += 120;
      if (!safe) s -= 60 * threats(state, color, to);
    } else if (m.toStep >= HOME_COLUMN_START) s += 150;
    if (m.fromStep === IN_YARD) s += 90 + (tokensOf(state, color).some((t) => t.step >= 0 && t.step < FINISH_STEP) ? 0 : 200);
    return s;
  };
  return moves.reduce((best, m) => (score(m) > score(best) ? m : best));
}

function threats(state, color, target) {
  return state.tokens.filter((t) => {
    if (t.color === color) return false;
    const from = trackIndex(t.color, t.step);
    if (from === null) return false;
    const d = (target - from + TRACK_LENGTH) % TRACK_LENGTH;
    return d >= 1 && d <= 6 && t.step + d <= LAST_TRACK_STEP;
  }).length;
}
